<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,reactive,ref} from 'vue'
import {useWorkspace} from '../../app/workspace'
import {createLatestRequests,isCancelled} from '../../shared/api/client'
import {formatTimestamp} from '../../shared/time'
import FormDialog from '../../shared/components/FormDialog.vue'
import Pagination from '../../shared/components/Pagination.vue'
import {categories,initialConfig,names,statusNames,type Area,type Asset,type History} from './definitions'
import './analysis.css'
const props=defineProps<{area:Area}>(),{api,command,can,captureSession}=useWorkspace(),requests=createLatestRequests(api)
const rows=ref<Asset[]>([]),page=ref(1),total=ref(0),keyword=ref(''),category=ref(''),status=ref(''),busy=ref(false),error=ref(''),notice=ref(''),editor=ref(false),editing=ref<Asset|null>(null),selected=ref<Asset|null>(null),history=ref<History[]>([]),historyTotal=ref(0),historyPage=ref(1),revision=ref<Asset|null>(null)
const relationOptions=ref<{modeling:Asset[];models:Asset[]}>({modeling:[],models:[]})
const form=reactive({code:'',name:'',category:'',description:'',configuration:'',project_id:'',model_id:'',steps:'',applicability:''})
const transition=ref<{row:Asset;action:'ACTIVATE'|'DEACTIVATE'|'ARCHIVE'}|null>(null),transitionNote=ref(''),sample=ref<Asset|null>(null),sampleText=ref('[\n  {"record_count": 5}\n]'),sampleResult=ref('')
let applied={keyword:'',category:'',status:''}
const title=computed(()=>names[props.area]),writable=computed(()=>can(props.area+'.write'))
const recordName=computed(()=>({modeling:'建模项目',models:'业务模型',tactics:'技战法'})[props.area])
const actionLabels={ACTIVATE:'启用',DEACTIVATE:'停用',ARCHIVE:'归档'}
async function act(task:()=>Promise<void>){busy.value=true;error.value='';try{await task()}catch(e){if(!isCancelled(e))error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
async function load(target=page.value,filters=applied){const result=await requests.latest<{items:Asset[];total:number}>('list',`/analysis/${props.area}/search`,{method:'POST',body:JSON.stringify({...filters,status:filters.status||null,category:filters.category||null,page:target})});rows.value=result.items;page.value=target;total.value=result.total;applied={...filters}}
function resetConfig(){form.configuration=JSON.stringify(initialConfig[form.category]||{},null,2)}
async function edit(row?:Asset){await act(async()=>{const options=await requests.latest<typeof relationOptions.value>('options',`/analysis/${props.area}/options`);relationOptions.value=options;let value=row;if(row)value=(await requests.latest<{asset:Asset}>('editor',`/analysis/${props.area}/${row.id}`)).asset;editing.value=value||null;Object.assign(form,{code:value?.code||'',name:value?.name||'',category:value?.category||Object.keys(categories[props.area])[0],description:value?.description||'',project_id:value?.project_id||'',model_id:value?.model_id||'',steps:String(value?.configuration?.steps||''),applicability:String(value?.configuration?.applicability||'')});form.configuration=JSON.stringify(value?.configuration||initialConfig[form.category]||{},null,2);editor.value=true})}
async function save(){await act(async()=>{let configuration:object;try{configuration=props.area==='tactics'?{steps:form.steps,applicability:form.applicability}:JSON.parse(form.configuration)}catch{throw Error('配置不是有效 JSON，请检查括号、引号和逗号。')}if(Array.isArray(configuration)||!configuration||typeof configuration!=='object')throw Error('配置应为 JSON 对象。');const valid=captureSession(),row=editing.value;await command(`analysis-${props.area}-${row?.id||'new'}`,`/analysis/${props.area}`+(row?`/${row.id}/update`:''),{name:form.name,category:form.category,description:form.description,configuration,project_id:form.project_id||null,model_id:form.model_id||null,...(row?{version:row.version}:{code:form.code})});if(!valid())return;editor.value=false;notice.value='资料已保存';await load(row?page.value:1)})}
async function show(id:string,target=1){await act(async()=>{const response=await requests.latest<{asset:Asset;history:{items:History[];total:number;page:number}}>('detail',`/analysis/${props.area}/${id}?page=${target}`);selected.value=response.asset;history.value=response.history.items;historyTotal.value=response.history.total;historyPage.value=response.history.page;revision.value=null})}
async function change(){if(!transition.value)return;await act(async()=>{const current=captureSession(),{row,action}=transition.value!;await command(`analysis-state-${row.id}`,`/analysis/${props.area}/${row.id}/transition`,{version:row.version,action,note:transitionNote.value});if(!current())return;transition.value=null;transitionNote.value='';notice.value='状态已更新';await load()})}
async function validateSample(){if(!sample.value)return;await act(async()=>{let records:unknown;try{records=JSON.parse(sampleText.value)}catch{throw Error('样例不是有效 JSON。')}if(!Array.isArray(records))throw Error('请填写字段对象数组，例如 [{"record_count":5}]。');const result=await requests.latest('sample',`/analysis/models/${sample.value!.id}/validate`,{method:'POST',body:JSON.stringify({version:sample.value!.version,records})});sampleResult.value=JSON.stringify(result,null,2)})}
onMounted(()=>{void act(()=>load(1))});onBeforeUnmount(()=>requests.dispose())
</script>
<template>
  <div class="page-list analysis-workspace"><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="success" role="status">{{notice}}</p><div class="list-toolbar"><slot name="navigation"/><button v-if="writable" type="button" :disabled="busy" @click="edit()">{{area==='modeling'?'新建项目':area==='models'?'新增模型':'新增技战法'}}</button></div><section class="card"><form class="list-filters" @submit.prevent="act(()=>load(1,{keyword,category,status}))"><label class="list-filter-keyword">编号或名称<input v-model="keyword" maxlength="100" placeholder="输入编号或名称"></label><label class="list-filter-select">分类<select v-model="category"><option value="">全部分类</option><option v-for="(label,key) in categories[area]" :key="key" :value="key">{{label}}</option></select></label><label class="list-filter-select">状态<select v-model="status"><option value="">全部状态</option><option v-for="(label,key) in statusNames" :key="key" :value="key">{{label}}</option></select></label><div class="list-filter-actions"><button :disabled="busy">查询</button><button type="button" class="secondary" :disabled="busy" @click="keyword='';category='';status='';act(()=>load(1,{keyword:'',category:'',status:''}))">重置</button></div></form>
  <div class="table-wrap"><table><thead><tr><th scope="col" class="row-number">序号</th><th scope="col">编号</th><th scope="col">名称</th><th scope="col">分类</th><th scope="col">状态</th><th scope="col">版本</th><th scope="col">更新时间</th><th scope="col">操作</th></tr></thead><tbody><tr v-for="(row,index) in rows" :key="row.id"><td class="row-number">{{(page-1)*20+index+1}}</td><td>{{row.code}}</td><td>{{row.name}}</td><td>{{categories[area][row.category]||row.category}}</td><td><span class="tag">{{statusNames[row.status]}}</span></td><td>{{row.version}}</td><td>{{formatTimestamp(row.updated_at)}}</td><td><button class="link" :disabled="busy" @click="show(row.id)">查看</button><button v-if="writable&&row.status==='DRAFT'" class="link" :disabled="busy" @click="edit(row)">编辑</button><button v-if="area==='models'&&row.status!=='ARCHIVED'" class="link" :disabled="busy" @click="sample=row;sampleResult='';error=''">样例验证</button><button v-if="writable&&row.status!=='ARCHIVED'" class="link" :disabled="busy" @click="transition={row,action:row.status==='ACTIVE'?'DEACTIVATE':'ACTIVATE'};transitionNote='';error=''">{{row.status==='ACTIVE'?'停用':'启用'}}</button><button v-if="writable&&row.status==='DRAFT'" class="link" :disabled="busy" @click="transition={row,action:'ARCHIVE'};transitionNote='';error=''">归档</button></td></tr></tbody></table><p v-if="!rows.length&&!busy" class="empty">暂无{{title}}记录</p></div><Pagination :page="page" :total="total" :loading="busy" @change="act(()=>load($event))"/></section>
  <FormDialog v-if="editor" :title="(editing?'编辑':'新增')+recordName" :wide="true" :busy="busy" :error="error" @close="editor=false"><form @submit.prevent="save"><div class="analysis-form-grid"><label>编号<input v-model="form.code" pattern="[A-Za-z0-9][A-Za-z0-9_-]*" maxlength="80" :disabled="!!editing" required placeholder="字母、数字、下划线或连字符"></label><label>名称<input v-model="form.name" maxlength="200" required></label><label>分类<select v-model="form.category" @change="resetConfig"><option v-for="(label,key) in categories[area]" :key="key" :value="key">{{label}}</option></select></label><label v-if="area!=='modeling'">关联建模项目<select v-model="form.project_id"><option value="">不关联</option><option v-for="row in relationOptions.modeling" :key="row.id" :value="row.id">{{row.name}}（{{statusNames[row.status]}}）</option></select></label><label v-if="area==='tactics'">关联业务模型<select v-model="form.model_id"><option value="">不关联</option><option v-for="row in relationOptions.models" :key="row.id" :value="row.id">{{row.name}}（{{statusNames[row.status]}}）</option></select></label></div><label>用途说明<textarea v-model="form.description" maxlength="2000" required></textarea></label><template v-if="area==='tactics'"><label>适用场景<textarea v-model="form.applicability" maxlength="2000"></textarea></label><label>操作步骤<textarea v-model="form.steps" maxlength="10000" rows="8" required placeholder="分步填写输入、分析方法、核验与输出"></textarea></label></template><template v-else><label>{{area==='modeling'?'字段结构（JSON）':'模型配置（JSON）'}}<textarea v-model="form.configuration" class="analysis-json" maxlength="20000" rows="12" required spellcheck="false"></textarea></label><p class="muted analysis-hint">{{area==='modeling'?'字段类型支持 text、number、date、boolean；字段名不能重复。':'条件运算支持 eq、ne、gt、gte、lt、lte、contains、in；评分规则总分不超过 100，流程模型维护步骤清单。'}}</p></template><button :disabled="busy">保存资料</button></form></FormDialog>
  <FormDialog v-if="transition" :title="actionLabels[transition.action]+recordName" :busy="busy" :error="error" @close="transition=null"><p>{{transition.row.code}} · {{transition.row.name}}</p><p class="muted">{{transition.action==='ACTIVATE'?'启用前需先启用关联项目和模型。':transition.action==='DEACTIVATE'?'停用后恢复为未启用，可继续编辑；存在启用中的关联记录时须先停用关联记录。':'归档后保留资料和版本历史，不再编辑或启用。'}}</p><form @submit.prevent="change"><label>操作说明<textarea v-model="transitionNote" maxlength="1000" required></textarea></label><button :disabled="busy">确认{{actionLabels[transition.action]}}</button></form></FormDialog>
  <FormDialog v-if="selected" :title="selected.name+' · 详情'" :wide="true" :busy="busy" :error="error" @close="selected=null"><p>{{selected.code}} · {{categories[area][selected.category]}} · {{statusNames[selected.status]}} · 版本 {{selected.version}}</p><p class="analysis-text">{{selected.description}}</p><pre class="analysis-result">{{JSON.stringify(selected.configuration,null,2)}}</pre><h3>版本历史</h3><div class="table-wrap"><table><thead><tr><th class="row-number">序号</th><th>动作</th><th>说明</th><th>时间</th><th>操作</th></tr></thead><tbody><tr v-for="(event,index) in history" :key="event.id"><td class="row-number">{{(historyPage-1)*20+index+1}}</td><td>{{({CREATED:'创建',UPDATED:'修改',ACTIVATE:'启用',DEACTIVATE:'停用',ARCHIVE:'归档'} as Record<string,string>)[event.action]||event.action}}</td><td>{{event.note}}</td><td>{{formatTimestamp(event.created_at)}}</td><td><button class="link" @click="revision=event.snapshot">查看版本</button></td></tr></tbody></table></div><Pagination :page="historyPage" :total="historyTotal" :loading="busy" @change="show(selected!.id,$event)"/><pre v-if="revision" class="analysis-result">{{JSON.stringify(revision,null,2)}}</pre></FormDialog>
  <FormDialog v-if="sample" title="业务模型样例验证" :wide="true" :busy="busy" :error="error" @close="sample=null"><p>{{sample.code}} · {{sample.name}} · 版本 {{sample.version}}</p><form @submit.prevent="validateSample"><label>样例数据（JSON 数组）<textarea v-model="sampleText" class="analysis-json" maxlength="20000" rows="7" required></textarea></label><p class="muted analysis-hint">仅验证手工样例，不读取案件或人员数据。分析流程只预览步骤，不执行后台任务。</p><button :disabled="busy">验证样例</button></form><pre v-if="sampleResult" class="analysis-result" role="status">{{sampleResult}}</pre></FormDialog>
  </div>
</template>
